impl Equilibrator for PhaseEquilibrator {
    fn trusted_aqueous_readback(
        &mut self,
    ) -> Option<&mut dyn crate::aqueous_continuation::TrustedAqueousReadback> {
        // Characterization-only bridge: solvent phase settlement still belongs
        // to equilibrate(), and is not implied by a current aqueous receipt.
        self.chemistry.trusted_aqueous_readback()
    }

    fn name(&self) -> &'static str {
        "phase-coupled"
    }

    fn chemistry_applies(&self, vessel: &Vessel) -> bool {
        self.chemistry.chemistry_applies(vessel)
    }

    fn equilibrate(&mut self, vessel: &mut Vessel) -> Result<Vec<Event>, SolveError> {
        equilibrate_phase_coupled(self.chemistry.as_mut(), vessel)
    }

    fn mix(
        &mut self,
        vessel: &mut Vessel,
        soln_a: &Vessel,
        frac_a: f64,
        soln_b: &Vessel,
        frac_b: f64,
    ) -> Option<Result<Vec<Event>, SolveError>> {
        self.chemistry.mix(vessel, soln_a, frac_a, soln_b, frac_b)
    }
}

